//! TB-303 voice derived from the pinned OpenRB-338 implementation (GPL-3.0-only).
//! The coefficient and pitch tables were generated by its table builder.
use rb_model::{Note, Synth};

const FILTER: &[u8; 131072] = include_bytes!("acid_filter.bin");
const PITCH: &[u8; 24576] = include_bytes!("acid_pitch.bin");
const OFFSET: f64 = f32::from_bits(0x3586_37bd) as f64;
const DC: f64 = f32::from_bits(0x3f7c_60e3) as f64;
fn byte(value: f32) -> u8 {
    (value.clamp(0., 1.) * 127.).round() as u8
}
fn word(data: &[u8], i: usize) -> f32 {
    f32::from_le_bytes(data[i * 4..i * 4 + 4].try_into().unwrap())
}
fn filter(row: usize, index: usize) -> [f32; 4] {
    std::array::from_fn(|k| word(FILTER, (row * 1024 + index.min(1023)) * 4 + k))
}
fn square_n(x: f32, n: u32) -> f32 {
    let mut v = x as f64;
    for _ in 0..n {
        v *= v;
    }
    v as f32
}
fn controls(c: &Synth) -> [u8; 5] {
    [
        byte((c.cutoff - 100.) / 5900.),
        byte(c.resonance),
        byte(c.envelope / 5000.),
        byte((c.decay - 0.05) / 0.75),
        byte(c.accent),
    ]
}

pub struct AcidVoice {
    sr: f32,
    phase: f64,
    s: f64,
    y1: f64,
    y2: f64,
    out: f64,
    pitch: u32,
    target: u32,
    slide: bool,
    gate: f64,
    gate_samples: f32,
    amp_in: f64,
    amp_fb: f64,
    amp: f64,
    env: f64,
    env_decay: f32,
    acc_amount: f32,
    acc_env: f32,
    acc_coef: f32,
    cs1: f32,
    cs2: f32,
    coefs: [f64; 4],
    steps: [f64; 4],
    retrig: bool,
    vintage: bool,
    pos: usize,
    inc: f64,
    cutoff: f64,
    amp_block: f64,
    env_block: f64,
}
impl AcidVoice {
    pub fn new(sr: f32) -> Self {
        Self {
            sr,
            phase: 0.,
            s: 0.,
            y1: 0.,
            y2: 0.,
            out: 0.,
            pitch: 0,
            target: 0,
            slide: false,
            gate: 0.,
            gate_samples: 0.,
            amp_in: 0.,
            amp_fb: 0.,
            amp: 0.,
            env: 0.,
            env_decay: 0.,
            acc_amount: 0.,
            acc_env: 0.,
            acc_coef: 0.,
            cs1: 0.5,
            cs2: 0.5,
            coefs: [0.; 4],
            steps: [0.; 4],
            retrig: false,
            vintage: false,
            pos: 0,
            inc: 0.,
            cutoff: 0.,
            amp_block: 0.,
            env_block: 0.,
        }
    }
    pub fn clear(&mut self) {
        *self = Self::new(self.sr);
    }
    pub fn silence(&mut self) {
        self.slide = false;
        self.note_off();
        self.gate_samples = 0.;
    }
    pub fn gate_off(&mut self) {
        self.note_off();
        self.gate_samples = 0.;
    }
    pub fn note_block(&mut self, note: &Note, cfg: &Synth, vintage: bool) {
        self.note(note, cfg, f32::INFINITY, vintage);
        self.gate_samples = f32::INFINITY;
    }
    fn note_off(&mut self) {
        if !self.slide {
            self.gate = 0.;
            (self.amp_in, self.amp_fb) = if self.vintage {
                (0.1f32 as f64, 0.9f32 as f64)
            } else {
                (0.063f32 as f64, 0.937f32 as f64)
            };
        }
    }
    pub fn note(&mut self, note: &Note, cfg: &Synth, duration: f32, vintage: bool) {
        self.vintage = vintage;
        let [_, resonance, _, decay, accent] = controls(cfg);
        let n = if vintage { 2 } else { 6 };
        self.acc_coef = square_n(((resonance as f64 / 12700. + 0.99) * 0.999) as f32, n);
        if note.accent {
            self.env_decay = square_n(f32::from_bits(0x3f7f_ebaf), n);
            self.acc_amount = (accent as f64 * (3. / 127.)) as f32;
        } else {
            let d = 1. - decay as f64 * f32::from_bits(0x3c01_0204) as f64;
            self.env_decay = square_n((0.99999 - d * d * 0.0003) as f32, n);
            self.acc_amount = 0.;
        }
        if note.gate {
            self.gate = 1.;
            (self.amp_in, self.amp_fb) = if vintage {
                (0.1f32 as f64, 0.9f32 as f64)
            } else {
                (1., 0.)
            };
            if !self.slide {
                self.env = 1.;
                self.retrig = true;
            }
        }
        let semis = (note.note as i32 + cfg.tune.round() as i32).clamp(0, 95);
        self.target = (semis as u32) << 10;
        if !self.slide {
            self.pitch = self.target;
        }
        self.slide = note.slide;
        self.gate_samples = if note.slide && note.gate {
            f32::INFINITY
        } else if note.gate || self.gate != 0. {
            (duration.max(0.001) * 0.5 * self.sr).max(1.)
        } else {
            0.
        };
    }
    fn interpolate(c: f64, res: u8) -> [f64; 4] {
        let idx = ((c.clamp(0., 1.) as f32 as f64) * 1023.) as usize;
        let r = res as f64 * f32::from_bits(0x3c00_feb7) as f64 * 7.;
        let lo = r as usize;
        let frac = r - lo as f64;
        let a = filter(lo, idx);
        let b = filter((lo + 1).min(7), idx);
        std::array::from_fn(|k| (a[k] as f64 + (b[k] as f64 - a[k] as f64) * frac) as f32 as f64)
    }
    fn block(&mut self, cfg: &Synth) {
        let [cut, res, em, _, _] = controls(cfg);
        let w = f64::from_bits(0x3fb0_15bf_8c18_0485);
        let a0 = (-w / 2.).exp() * (w.cos() * 2.);
        let b0 = (-w).exp();
        let a = a0 as f32 as f64;
        let b = b0 as f32 as f64;
        let g = ((1. - a0) + b0) as f32 as f64;
        let cs = (a * self.cs1 as f64 + (cut as f64 * 0.0022834645669291337 + 0.46) * g)
            - b * self.cs2 as f64;
        self.cs2 = self.cs1;
        self.cs1 = cs as f32;
        self.cutoff = cs;
        self.pitch = self.pitch.wrapping_mul(11).wrapping_add(self.target) / 12;
        self.inc = word(PITCH, ((self.pitch >> 4) as usize).min(6143)) as f64;
        self.amp_block = self.amp + OFFSET;
        self.env_block = self.env + OFFSET;
        if !self.vintage {
            let amp = self.amp_block * self.amp_fb + self.gate * self.amp_in;
            let acc = self.acc_coef as f64 * self.acc_env as f64
                + self.env_block * ((1. - self.acc_coef as f64) * self.acc_amount as f64);
            self.acc_env = acc as f32;
            let gain = amp * (acc + 1.);
            let ka = 0.10166666666666667 - (res as f64 / 127.) / 15.;
            let em = em as f64 * 0.0029921259842519685 + 0.08;
            if self.retrig {
                let c = ka * self.acc_env as f64 + ((self.env_block - 0.4) * em + cs);
                self.coefs = Self::interpolate(c, res);
                self.coefs[2] = 0.;
                self.retrig = false;
            }
            let e1 = self.env_block * self.env_decay as f64;
            let c = ka * self.acc_env as f64 + ((e1 - 0.4) * em + cs);
            let mut next = Self::interpolate(c, res);
            next[2] *= gain;
            for k in 0..4 {
                self.steps[k] = (next[k] - self.coefs[k]) / 32.;
            }
            self.env_block = e1;
            self.amp_block = amp;
        }
    }
    pub fn sample(&mut self, cfg: &Synth) -> f32 {
        if self.pos == 0 {
            self.block(cfg);
        }
        if self.vintage && self.pos % 4 == 0 {
            let [_, res, em, _, _] = controls(cfg);
            let e1 = self.env_block * self.env_decay as f64;
            let acc = self.acc_coef as f64 * self.acc_env as f64
                + self.env_block * ((1. - self.acc_coef as f64) * self.acc_amount as f64);
            self.acc_env = acc as f32;
            self.amp_block = self.amp_block * self.amp_fb + self.gate * self.amp_in;
            let ka = 0.10166666666666667 - (res as f64 * f32::from_bits(0x3c01_0204) as f64) / 15.;
            let c =
                ((e1 - 0.4) * (em as f64 * 0.0029921259842519685 + 0.08) + self.cutoff) + acc * ka;
            let f = filter((res >> 4) as usize, (c.clamp(0., 1.) * 1023.) as usize);
            self.coefs = [
                f[0] as f64,
                f[1] as f64,
                (acc + 1.) * self.amp_block * f[2] as f64,
                f[3] as f64,
            ];
            self.env_block = e1;
        }
        self.phase += self.inc;
        if self.phase > 1. {
            self.phase -= 2.;
        }
        let x = match cfg.wave.as_str() {
            "square" => {
                if self.phase <= f32::from_bits(0x3d3b_8000) as f64 {
                    f32::from_bits(0xbf0c_a000) as f64
                } else {
                    f32::from_bits(0x3f0c_a000) as f64
                }
            }
            "sine" => (self.phase * std::f64::consts::PI).sin(),
            "triangle" => 1. - 2. * self.phase.abs(),
            _ => self.phase,
        };
        self.s = self.s * self.coefs[3] + x;
        let y = (self.s * self.coefs[2] + self.y1 * self.coefs[0]) - self.y2 * self.coefs[1];
        self.out = (y - self.y1) + self.out * DC;
        self.y2 = self.y1;
        self.y1 = y;
        let out = self.out as f32;
        if !self.vintage && self.pos % 2 == 1 {
            for k in 0..4 {
                self.coefs[k] += self.steps[k];
            }
        }
        self.pos += 1;
        if self.pos == 64 {
            self.pos = 0;
            self.phase = self.phase as f32 as f64;
            self.s = self.s as f32 as f64;
            self.y1 = self.y1 as f32 as f64;
            self.y2 = self.y2 as f32 as f64;
            self.out = self.out as f32 as f64;
            self.env = self.env_block as f32 as f64;
            self.amp = self.amp_block as f32 as f64;
            if !self.vintage {
                self.coefs = self.coefs.map(|x| x as f32 as f64);
            }
        }
        if self.gate_samples.is_finite() && self.gate_samples > 0. {
            self.gate_samples -= 1.;
            if self.gate_samples <= 0. {
                self.note_off();
            }
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn matches_reference_voice_blocks() {
        let reference = include_bytes!("acid_reference.bin");
        for (case, (vintage, square)) in
            [(false, false), (false, true), (true, false), (true, true)]
                .into_iter()
                .enumerate()
        {
            let mut c = rb_model::Song::default().synth[0].clone();
            c.cutoff = 100. + 5900. * 64. / 127.;
            c.resonance = 90. / 127.;
            c.envelope = 5000. * 40. / 127.;
            c.decay = 0.05 + 0.75 * 80. / 127.;
            c.accent = 64. / 127.;
            c.tune = 0.;
            c.wave = if square { "square" } else { "saw" }.into();
            let mut v = AcidVoice::new(44100.);
            v.note(
                &Note {
                    note: 48,
                    gate: true,
                    slide: false,
                    accent: true,
                },
                &c,
                10.,
                vintage,
            );
            let mut max = 0f32;
            for i in 0..4096 {
                if i == 2048 {
                    v.note_off();
                }
                let actual = v.sample(&c);
                let expected = word(reference, case * 4096 + i);
                max = max.max((actual - expected).abs());
            }
            assert!(max < 1e-5, "case {case}, max difference {max}");
        }
    }
    #[test]
    fn matches_reference_sequence_with_slide_rest_and_controls() {
        let reference = include_bytes!("acid_sequence_reference.bin");
        for (case, vintage) in [false, true].into_iter().enumerate() {
            let mut c = rb_model::Song::default().synth[0].clone();
            c.cutoff = 100. + 5900. * 64. / 127.;
            c.resonance = 90. / 127.;
            c.envelope = 5000. * 40. / 127.;
            c.decay = 0.05 + 0.75 * 80. / 127.;
            c.accent = 64. / 127.;
            c.tune = 0.;
            c.wave = "saw".into();
            let mut v = AcidVoice::new(44100.);
            let note = |pitch, slide, accent, gate| Note {
                note: pitch,
                slide,
                accent,
                gate,
            };
            let mut max = 0f32;
            for block in 0..96 {
                match block {
                    0 => v.note_block(&note(48, true, false, true), &c, vintage),
                    12 => v.gate_off(),
                    16 => v.note_block(&note(55, false, true, true), &c, vintage),
                    24 => {
                        c.cutoff = 100. + 5900. * 30. / 127.;
                        c.resonance = 110. / 127.;
                        c.envelope = 5000. * 100. / 127.;
                        c.decay = 0.05 + 0.75 * 20. / 127.;
                        c.accent = 100. / 127.;
                    }
                    28 => v.gate_off(),
                    32 => {
                        c.tune = 2.;
                        v.note_block(&note(50, true, false, false), &c, vintage);
                    }
                    48 => v.note_block(&note(52, false, false, true), &c, vintage),
                    60 => v.gate_off(),
                    64 => {
                        c.tune = -1.;
                        c.wave = "square".into();
                        v.note_block(&note(57, false, true, true), &c, vintage);
                    }
                    76 => v.gate_off(),
                    _ => {}
                }
                for frame in 0..64 {
                    let i = block * 64 + frame;
                    let actual = v.sample(&c);
                    let expected = word(reference, case * 96 * 64 + i);
                    max = max.max((actual - expected).abs());
                }
            }
            assert!(max < 1e-5, "vintage {vintage}, max difference {max}");
        }
    }
}
